// Telegram sends the same photo at several resolutions in message.photo, sorted smallest to
// largest — take the last one (highest resolution) for the clearest read on small receipt print.
const photos = $json.message.photo;
const largest = photos[photos.length - 1];
return [{ json: { chatId: $json.message.chat.id, fileId: largest.file_id } }];

